import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DGYbyS8e.js";var i=JSON.parse(`{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":1787724520000}`),a={name:`api.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API reference”">​</a></h1><p>The API reference is organized as a set of short pages, following the same separation used by established Julia MRI documentation: each page focuses on one public type, constructor, or closely related function family. Scientific derivations and validation requirements remain in the <a href="/HighOrderMRI.jl/dev/theory/encoding-model">Theory</a> and <a href="/HighOrderMRI.jl/dev/guide/operators">Guide</a> sections.</p><h2 id="encoding-model-and-operators" tabindex="-1">Encoding model and operators <a class="header-anchor" href="#encoding-model-and-operators" aria-label="Permalink to “Encoding model and operators”">​</a></h2><ul><li><a href="/HighOrderMRI.jl/dev/reference/grid-basis"><code>Grid</code> and <code>basisfunc_spha</code></a>: physical reconstruction grid and real solid-harmonic basis evaluation.</li><li><a href="/HighOrderMRI.jl/dev/reference/highorderop"><code>HighOrderOp</code></a>: array-based explicit field-aware encoding.</li><li><a href="/HighOrderMRI.jl/dev/reference/highorderkernelop"><code>HighOrderKernelOp</code></a>: fused explicit CUDA encoding with optional multi-GPU voxel decomposition.</li><li><a href="/HighOrderMRI.jl/dev/reference/highorderlowrankop"><code>HighOrderLowRankOp</code></a>: low-rank residual-phase representation with an incremental shared spatial basis.</li></ul><h2 id="reconstruction" tabindex="-1">Reconstruction <a class="header-anchor" href="#reconstruction" aria-label="Permalink to “Reconstruction”">​</a></h2><ul><li><a href="/HighOrderMRI.jl/dev/reference/recon-hoop"><code>recon_HOOp</code></a>: iterative reconstruction wrapper.</li><li><a href="/HighOrderMRI.jl/dev/reference/sampling-density"><code>samplingDensity</code></a>: square-root sampling-density weights for non-Cartesian reconstruction.</li></ul><h2 id="coil-compression" tabindex="-1">Coil compression <a class="header-anchor" href="#coil-compression" aria-label="Permalink to “Coil compression”">​</a></h2><ul><li><a href="/HighOrderMRI.jl/dev/reference/coil-compression-transform"><code>CoilCompressionTransform</code></a>: fitted linear receive-coil transform.</li><li><a href="/HighOrderMRI.jl/dev/reference/estimate-noise-covariance"><code>estimate_noise_covariance</code></a>: complex receive-noise covariance estimation.</li><li><a href="/HighOrderMRI.jl/dev/reference/noise-prewhitening-scale"><code>noise_prewhitening_scale_factor</code></a>: dwell-time / receiver-bandwidth scale factor.</li><li><a href="/HighOrderMRI.jl/dev/reference/fit-coil-compression"><code>fit_coil_compression</code></a>: fit global SVD or noise-whitened SVD compression.</li><li><a href="/HighOrderMRI.jl/dev/reference/apply-coil-compression"><code>apply_coil_compression</code></a>: apply a fitted transform along a selected coil dimension.</li><li><a href="/HighOrderMRI.jl/dev/reference/compress-coils"><code>compress_coils</code></a>: fit one transform and apply it consistently to data and CSM.</li></ul><h2 id="field-prediction-and-synchronization" tabindex="-1">Field prediction and synchronization <a class="header-anchor" href="#field-prediction-and-synchronization" aria-label="Permalink to “Field prediction and synchronization”">​</a></h2><ul><li><a href="/HighOrderMRI.jl/dev/reference/girf-model"><code>GIRFModel</code></a>: typed frequency-domain GIRF representation.</li><li><a href="/HighOrderMRI.jl/dev/reference/apply-girf"><code>apply_girf</code></a>: predict realized field channels from nominal physical gradients.</li><li><a href="/HighOrderMRI.jl/dev/reference/interp-traj-time"><code>InterpTrajTime</code></a>: interpolate field/trajectory coefficients to requested ADC times.</li><li><a href="/HighOrderMRI.jl/dev/reference/find-delay"><code>FindDelay</code></a>: single-acquisition model-based field/data synchronization.</li><li><a href="/HighOrderMRI.jl/dev/reference/find-delay-multishot"><code>FindDelay_multishot</code></a>: shared-delay estimation for multi-shot data.</li></ul><h2 id="metrics-and-utilities" tabindex="-1">Metrics and utilities <a class="header-anchor" href="#metrics-and-utilities" aria-label="Permalink to “Metrics and utilities”">​</a></h2><ul><li><a href="/HighOrderMRI.jl/dev/reference/image-metrics">Reconstruction metrics</a>: raw and aligned complex NRMSE, magnitude NRMSE, SSIM, and compatibility helpers.</li><li><a href="/HighOrderMRI.jl/dev/reference/utilities">Array and signal utilities</a>: CPU/GPU conversion, trajectory-gradient conversion, resizing, cropping, and factor helpers.</li><li><a href="/HighOrderMRI.jl/dev/reference/plotting">Plotting helpers</a>: common visualization functions.</li><li><a href="/HighOrderMRI.jl/dev/reference/resources">Resource lifecycle</a>: explicit cleanup and safe replacement of large low-rank operators.</li></ul><div class="tip custom-block"><p class="custom-block-title">Reference vs. methods</p><p>Use these pages to check calling conventions and returned objects. Use <a href="/HighOrderMRI.jl/dev/theory/symbols">Symbols and notation</a>, the <a href="/HighOrderMRI.jl/dev/theory/encoding-model">expanded encoding model</a>, <a href="/HighOrderMRI.jl/dev/theory/low-rank">low-rank shared subspace</a>, and the relevant Guide page when interpreting units, phase conventions, approximation parameters, or validation requirements.</p></div>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};